// Validate and normalize structured output from AI Agent
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

// Try to extract JSON from various formats
let parsed;
try {
  // Try markdown code block first
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) {
    parsed = JSON.parse(mdMatch[1].trim());
  } else {
    // Try to find JSON object in the text
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = JSON.parse(output);
    }
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Failed to parse structured output: ' + e.message,
      raw_output: output.substring(0, 3000),
      analysis: { intent_summary: 'Parse error', domain: 'unknown', scope: '', stakeholders: [], key_entities: [], key_processes: [] },
      requirements: { functional: [], non_functional: [], constraints: [], assumptions: [] },
      inputs_summary: { jira_tickets: [], documents_referenced: [], themes_identified: [] },
      recommendations: { suggested_doc_type: 'requirements', suggested_sections: [], gaps: ['Failed to parse AI output - please review raw output'] }
    }
  }];
}

// Ensure all required sections exist with defaults
const defaults = {
  analysis: { intent_summary: '', domain: '', scope: '', stakeholders: [], key_entities: [], key_processes: [] },
  requirements: { functional: [], non_functional: [], constraints: [], assumptions: [] },
  inputs_summary: { jira_tickets: [], documents_referenced: [], themes_identified: [] },
  recommendations: { suggested_doc_type: 'requirements', suggested_sections: [], gaps: [] }
};

for (const [key, value] of Object.entries(defaults)) {
  if (!parsed[key] || typeof parsed[key] !== 'object') parsed[key] = value;
  for (const [subKey, subValue] of Object.entries(value)) {
    if (parsed[key][subKey] === undefined) parsed[key][subKey] = subValue;
  }
}

// Validate critical fields
const errors = [];
if (!parsed.analysis.intent_summary) errors.push('Missing analysis.intent_summary');
if (!Array.isArray(parsed.requirements.functional)) errors.push('requirements.functional must be an array');
if (!Array.isArray(parsed.requirements.non_functional)) errors.push('requirements.non_functional must be an array');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: 'Validation errors: ' + errors.join('; '),
      raw_output: output.substring(0, 3000),
      parsed: parsed
    }
  }];
}

return [{
  json: {
    valid: true,
    ...parsed
  }
}];
